/**
 * The shipped hub clip libraries (clip-library.js), loaded by id only when a world names one, so nothing else carries
 * their bytes. Each is generated by scripts/import-clip-library.mjs from the library's own file.
 *
 *   quaternius-ual   Quaternius, Universal Animation Library (free CC0 edition): idle, walk, jog, sprint, the jump
 *                    (start, loop, land), crouch idle and walk, a hit
 */
const LOADERS = {
  'quaternius-ual': () => import('./quaternius-ual.js'),
};
export const CLIP_LIBRARY_IDS = Object.freeze(Object.keys(LOADERS));

/** A library by id: { id, map, licence, source, rest, clips }. */
export async function loadClipLibrary(id) {
  const L = LOADERS[id];
  if (!L) throw new Error(`clip library '${id}' is not shipped (libraries: ${CLIP_LIBRARY_IDS.join(', ')})`);
  return (await L()).default;
}

/** A library clip plays once and holds unless its name says it loops (the libraries' own `_Loop` convention). */
export const clipLoops = (name) => /_Loop$|^Loop_|_loop$/.test(name);
